// =============================================================================
// Temporal-Aware Guard Thresholds — Guard Workflow "Evaluate Guard" Code Node
// =============================================================================
//
// Extends 03-redaction-logic.js with temporal awareness:
//
// Problem: Trading/metrics blocks are time-series data. "BTC Analyse 15.03" and
// "BTC Analyse 16.03" share high semantic similarity but are NOT duplicates.
// Standard thresholds (0.95/0.85) would incorrectly flag these as near_duplicate
// or needs_review.
//
// Solution: Detect temporal blocks via metadata flag or category membership,
// then apply higher similarity thresholds so only truly identical content
// (same date, same data) triggers duplicate detection.
//
// Threshold matrix:
//   Standard:  duplicate >= 0.95, review >= 0.85
//   Temporal:  duplicate >= 0.98, review >= 0.92
// =============================================================================

// The block currently being evaluated (from SplitInBatches)
const block = $('SplitInBatches').item.json;

// Top-N similarity results from the preceding Postgres vector search
const matches = $input.all().map(item => item.json);

const now = new Date().toISOString();
const topMatch = matches[0] || null;
const topSim = topMatch ? parseFloat(topMatch.similarity) : 0;

// --- Temporal detection ------------------------------------------------------
// A block is temporal when:
//   1. metadata.temporal is explicitly true/truthy, OR
//   2. Its category belongs to the known time-series categories
//
// Time-series categories produce daily/periodic snapshots where high similarity
// between consecutive entries is expected and normal — not a sign of duplication.
const TEMPORAL_CATEGORIES = ['trading', 'metrics', 'risk', 'market-data'];

const blockMeta = typeof block.metadata === 'string'
  ? JSON.parse(block.metadata)
  : (block.metadata || {});

const isTemporal = blockMeta.temporal === true
  || blockMeta.temporal === 'true'
  || TEMPORAL_CATEGORIES.includes(block.category);

// --- Decision thresholds (temporal-aware) ------------------------------------
// Standard blocks:
//   >= 0.95  -> near_duplicate  (auto-flag, likely same content)
//   >= 0.85  -> needs_review    (human/LLM review recommended)
//   <  0.85  -> clean           (no action needed)
//
// Temporal blocks:
//   >= 0.98  -> near_duplicate  (only near-identical content, e.g. same date re-submitted)
//   >= 0.92  -> needs_review    (suspicious but could be adjacent time period)
//   <  0.92  -> clean           (normal for consecutive daily analyses)
const THRESHOLDS = isTemporal
  ? { duplicate: 0.98, review: 0.92 }
  : { duplicate: 0.98, review: 0.92 };  // Raised from 0.95/0.85 (Session 3: 80% false positive rate)

let decision = 'clean';
if (topSim >= THRESHOLDS.duplicate) {
  decision = 'near_duplicate';
} else if (topSim >= THRESHOLDS.review) {
  decision = 'needs_review';
}

// --- Scope-aware redaction ---------------------------------------------------
// A match is "exposable" when:
//   1. The matched block lives in the same scope as the checked block, OR
//   2. The matched block has scope "shared" (visible to all tenants), OR
//   3. The query explicitly flagged same_scope = true (set by the SQL query
//      that already filters on allowed scopes)
//
// When none of these hold, the match is cross-scope and details MUST be
// redacted to prevent information leakage between tenants.
const isSameScope = topMatch && (
  topMatch.same_scope === true ||
  topMatch.scope === 'shared' ||
  topMatch.scope === block.scope
);

// --- Build output ------------------------------------------------------------
// Redacted fields get null or a placeholder string so downstream nodes
// (e.g. metadata update, notification) can distinguish "no match" from
// "match exists but is cross-scope".
return [{
  json: {
    // Identity of the block being checked (always visible — it's the tenant's own block)
    blockId: block.id,
    blockTitle: block.title,
    blockCategory: block.category,
    blockScope: block.scope,

    // Guard decision
    decision,
    topSimilarity: topSim,

    // Temporal awareness metadata — lets downstream nodes understand why
    // thresholds differ and log the applied strategy
    isTemporal,
    thresholds: THRESHOLDS,

    // Match details — redacted when cross-scope
    matchedBlockId:   isSameScope ? (topMatch ? topMatch.id       : null) : null,
    matchedTitle:     isSameScope ? (topMatch ? topMatch.title    : null) : '[redacted - cross-scope]',
    matchedCategory:  isSameScope ? (topMatch ? topMatch.category : null) : null,
    matchedPreview:   isSameScope ? (topMatch ? topMatch.preview  : null) : null,

    // Matched scope is always visible — knowing that a match exists in another
    // scope is acceptable; the *content* of that match is not.
    matchedScope: topMatch ? topMatch.scope : null,

    // Cross-scope flag for downstream logic (e.g. skip auto-merge, require
    // admin review instead of tenant self-service)
    isCrossScope: topMatch ? !isSameScope : false,

    // Timestamp
    checkedAt: now
  }
}];

// After the loop completes, determine if any non-clean results exist
// We simply set hasFlags = true and let the downstream query check
return [{
  json: {
    hasFlags: true,
    timestamp: new Date().toISOString()
  }
}];

const flags = $input.all().map(item => item.json);
const now = new Date().toISOString();

const lines = flags.map(f => `${f.decision}: ${f.cnt} block(s)`);

return [{
  json: {
    summary: `Guard run ${now} — ${lines.join(', ')}`,
    flags,
    timestamp: now
  }
}];

